import { NextResponse } from 'next/server';
import { generateWithRetry } from '@/lib/gemini';
import { cleanAndParseJSON } from '@/lib/gemini-json';

export async function POST(req: Request) {
  if (!process.env.GEMINI_API_KEY) {
    return NextResponse.json(
      { error: 'Server configuration error: GEMINI_API_KEY is not set in .env.local' },
      { status: 500 }
    );
  }

  try {
    const { query, locale, injectEdgeCases } = await req.json();

    if (!query || query.trim() === '') {
      return NextResponse.json({ error: 'Document prompt is required' }, { status: 400 });
    }

    const prompt = `
You are a financial and legal document generator. Output ONLY valid JSON — no markdown, no explanation.

Request: ${query}

Config:
- Locale: ${locale || 'en-US'}
- Edge cases: ${injectEdgeCases ? 'Include unexpected fees, complex terms, unusual edge cases.' : 'Standard document.'}

Rules:
1. Include metadata (dates, IDs, parties, addresses).
2. Ensure financial calculations are accurate (subtotals, taxes, totals must add up).
3. Keep field values concise — avoid extremely long strings.

Output a single JSON object. Start with { and end with }.
`.trim();

    const raw = await generateWithRetry(prompt);
    const data = cleanAndParseJSON<Record<string, any>>(raw);

    return NextResponse.json({ data });

  } catch (error: any) {
    const message =
      error?.errorDetails?.[0]?.message ||
      error?.message ||
      'Internal Server Error';
    console.error('[/api/generate/document] Error:', message);
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
